// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Precondition: owner is the test contract
        address alice = address(0x1234);
        // First call: test contract calls setOwner(alice) as owner, reference sets owner to alice, bug sets owner to msg.sender = address(this)
        c.setOwner(alice);
        // Second call: alice tries to call setOwner(alice) again (though not owner)
        // But we need a scenario where reading owner shows difference
        // Actually, after first call, reference owner = alice, bug owner = address(this)
        // So check c.owner() == alice for reference, but bug has address(this)
        assertTrue(c.owner() != alice); // reference would fail (owner==alice), bug passes (owner != alice)
    }
}
